    }
}

public class Main {
    public static void main(String[] args) {
        List<Item> items = new ArrayList<>();
        items.add(new Item("pen", 2, 100));
        items.add(new Item("note", 1, 300));
        items.add(new Item("eraser", 5, 50));

        System.out.println("--- そのまま ---");
