import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;
import java.util.TreeMap;

record Item(String name, int count, int price) {
    int subtotal() {
        return count * price;
    }
}

public class Main {
    static String names(List<Item> items) {
        String s = "";
        for (Item item : items) {
            s += " " + item.name();
        }
        return s;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        List<Item> items = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            String name = sc.next();
            int count = sc.nextInt();
            int price = sc.nextInt();
            items.add(new Item(name, count, price));
        }

        List<Item> byCount = new ArrayList<>(items);
        byCount.sort(Comparator.comparingInt(Item::count).thenComparing(Item::name));
        System.out.println("個数順" + names(byCount));

        List<Item> byPrice = new ArrayList<>(items);
        byPrice.sort(Comparator.comparingInt(Item::price).reversed().thenComparing(Item::name));
        System.out.println("高い順" + names(byPrice));

        List<Item> mine = new ArrayList<>(items);
        mine.sort((x, y) -> {
            int bySubtotal = Integer.compare(x.subtotal(), y.subtotal());
            return bySubtotal != 0 ? bySubtotal : y.name().compareTo(x.name());
        });
        System.out.println("自作" + names(mine));

        TreeMap<String, Integer> stock = new TreeMap<>();
        for (Item item : items) {
            stock.put(item.name(), stock.getOrDefault(item.name(), 0) + item.count());
        }
        System.out.println("在庫 " + stock);
    }
}

