import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        String[] words = {"apple", "fig", "apple", "kiwi", "fig", "apple"};

        Map<String, Integer> counts = new HashMap<>();
        for (String w : words) {
            counts.put(w, counts.getOrDefault(w, 0) + 1);
        }
        System.out.println("異なる単語 " + counts.size());

        String best = null;
        int bestCount = 0;
        for (String key : new TreeSet<>(counts.keySet())) {
            System.out.println("  " + key + " → " + counts.get(key));
            if (counts.get(key) > bestCount) {
                best = key;
                bestCount = counts.get(key);
            }
        }
        System.out.println("最多 " + best + " " + bestCount);

        Set<String> longWords = new TreeSet<>();
        for (String w : words) {
            if (w.length() >= 3) {
                longWords.add(w);
            }
        }
        System.out.println("長い単語 " + longWords);
    }
}

