import java.util.Scanner;
import java.util.TreeMap;

class InvalidScoreException extends Exception {
    InvalidScoreException(String message) {
        super(message);
    }
}

public class Main {
    static int check(int score) throws InvalidScoreException {
        if (score < 0 || score > 100) {
            throw new InvalidScoreException("範囲外: " + score);
        }
        return score;
    }

    static String grade(int score) {
        return switch (score / 10) {
            case 10, 9 -> "A";
            case 8, 7 -> "B";
            case 6 -> "C";
            default -> "D";
        };
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        TreeMap<String, Integer> grades = new TreeMap<>();
        int max = -1;
        int min = 101;
        int invalid = 0;

        for (int i = 0; i < k; i++) {
            String name = sc.next();
            int score = sc.nextInt();

            try {
                int valid = check(score);
                String g = grade(valid);
                System.out.println(name + " " + g);
                grades.put(g, grades.getOrDefault(g, 0) + 1);
                if (valid > max) {
                    max = valid;
                }
                if (valid < min) {
                    min = valid;
                }
            } catch (InvalidScoreException e) {
                System.out.println(name + " " + e.getMessage());
                invalid++;
            }
        }

        System.out.println("評価 " + grades);
        System.out.println("最高 " + (max < 0 ? "なし" : String.valueOf(max)));
        System.out.println("最低 " + (min > 100 ? "なし" : String.valueOf(min)));
        System.out.println("無効 " + invalid);
    }
}

